    checklistTitle: "토익 점수 향상 체크리스트",
    checklistSub: "주 1회 점검",
    faqs: [
      {q: "토익 700점에서 900점 가능한가요?", a: "가능해요. 보통 6개월~1년 집중 학습이면 충분합니다. 핵심: (1) 약점 파트 진단·집중 보완. (2) 빈출 어휘 1500개 + 함정 패턴 50개. (3) 매주 실전 모의고사 + 오답 분석. (4) Part 7 시간 관리. 1:1 과외에서 진단 후 맞춤 커리큘럼 설계 가능합니다. 단, 본인 의지 + 매일 1시간 학습이 전제입니다."},
      {q: "단기간(2개월)에 100점 향상 가능한가요?", a: "현재 점수에 따라 달라요. 600~800점대는 약점 파트 집중·시간 관리 학습으로 100점 향상 충분히 가능합니다. 850점 이상은 어렵고 6개월 이상 필요해요. 무료 체험 수업에서 현재 실력 진단 후 정확한 향상 가능치 안내드려요. 단기 향상엔 매일 1시간 + 주 2회 모의고사가 표준입니다."},
      {q: "리스닝과 리딩 중 어느 영역을 먼저 올려야 하나요?", a: "리스닝부터 시작이 효과적이에요. (1) 리스닝은 단기 점수 향상이 빠름 (3개월 100점 가능). (2) 리딩은 어휘·문법 누적이라 시간이 오래 걸림. (3) 리스닝 점수가 자신감을 주어 학습 동기 ↑. 다만 480/480 리스닝 도달 후엔 리딩 집중이 답이에요. 균형이 핵심입니다."},
      {q: "토익 학원 vs 1:1 과외, 무엇이 효과적인가요?", a: "목표·기간에 따라 달라요. (1) 단기간(3개월 미만) 점수 향상: 1:1 과외가 효율적 (약점 파트만 집중). (2) 장기간(6개월+) 학습: 학원도 가능하지만 1:1이 시간 효율 4~5배. (3) 800점대 → 900점 도전: 1:1 권장 (정밀 약점 분석 필수). 그룹 수업은 다른 학생 진도 맞춰야 하고 약점 보완 어려워요. 1:1은 본인 약점만 집중 가능합니다."},
      {q: "토익 점수 유효 기간이 2년이라던데, 언제 봐야 하나요?", a: "토익 점수는 발표 후 2년간 유효해요. (1) 취업 준비: 입사 시점 기준 2년 이내 점수 필요. 졸업 1년 전 시점에 목표 점수 도달 추천. (2) 이직: 이직 시점 기준 2년 이내. (3) 승진: 회사 정책에 따라. 시험 일정은 매월 1~2회·금토 양일 시험. 시험 4~6주 전 신청이 안전합니다."},
    ],
