      body: "토플 iBT는 미국 대학·대학원 진학의 표준 시험이에요. 학부 입학 80~100점, 명문대 100점+, 대학원·MBA 100~110점이 표준입니다. 한국 학생들이 토플에서 점수가 안 오르는 이유는 \"학술 영어 부족·통합 문제 대비 미흡·스피킹/라이팅 약점\"이에요. 토익과 달리 토플은 \"학술적 글·강의·발표·에세이\"가 핵심이라 단순 시험 영어로는 부족합니다. 핵심은 \"리딩(54분)·리스닝(41분)·스피킹(17분)·라이팅(50분) 4영역 균형 + 통합 문제(Integrated) 4세트\" 5박자예요. 학습 단계: (1) 진단 모의고사 + 약점 영역 파악 → (2) 영역별 집중 보완 → (3) 통합 문제 반복 → (4) 실전 모의고사. 1:1 화상 과외에서는 4영역 진단·약점 집중 + 통합 문제 첨삭 사이클로 진행해요. 1:1 주 2회 30분부터 다양한 시간대로 맞춤 수업 받아보세요."
