      body: "영어 회화 고급은 \"전문 영역 + 뉘앙스 표현\"이 목표예요. 일상 대화를 넘어 비즈니스 회의·프레젠테이션·협상·토론·미디어 인터뷰 가능 수준입니다. 한국 학생들이 고급에서 정체되는 이유는 \"뉘앙스 부족·전문 어휘 약점·문화적 맥락 미숙\" 3가지예요. 고급 학습의 핵심은 \"뉘앙스 + 전문 어휘 + 문화적 맥락 + 자연스러운 흐름\" 4박자입니다. 1:1 화상 고급 수업에서는 중급 졸업 학생이 비즈니스·전문 영역에서 영어를 자유 구사하도록 단계별 학습해요. 학습 단계: (1) 뉘앙스 표현 (sarcastic·subtle·implicit) → (2) 전문 어휘 (자기 분야 영어) → (3) 비즈니스·프레젠테이션 → (4) 토론·협상·미디어 인터뷰. 1~2년 학습 → \"비즈니스 + 전문 분야 자유 구사\" 수준 도달이 목표예요. 매일 40분~1시간 + 주 2~3회 1:1 코칭이 가장 효과적인 고급 루틴이에요."
