    checklistTitle: "영어 수행평가 체크리스트",
    checklistSub: "평가 2주 전 점검",
    faqs: [
      {q: "수행평가가 너무 부담스러워요. 어떻게 준비하나요?", a: "단계별로 준비하면 부담이 줄어요. (1) 학기 시작: 학교 평가 유형 분석. (2) 1~2개월 전: 답안 작성 + 1:1 첨삭. (3) 2주 전: 발음·발표 연습 + 녹음. (4) 1주 전: 실전 시뮬레이션 + 자신감 코칭. (5) 평가 직전: 컨디션 조절 + 마지막 점검. 미리 준비 + 1:1 첨삭이 답이에요. 직전 벼락치기는 부담만 ↑."},
      {q: "발표 답안 어떻게 작성해야 하나요?", a: "답안 구조 4단계: (1) Introduction (10~15초): 인사 + 주제 도입 (\"Hello, today I'd like to talk about...\"). (2) Main Points (30~60초씩 3개): 핵심 포인트 3가지. (3) Examples (각 포인트마다): 본인 경험·예시·근거. (4) Conclusion (10~15초): 요약 + 마무리 (\"Thank you for listening\"). 각 발표 1~5분 정도. 1:1 과외에서 답안 첨삭·구조 학습 추천."},
      {q: "원고를 외워서 발표하는 게 좋나요?", a: "통째 외우기는 비추예요. 외운 티가 나고 즉흥 대응 어려워요. 답안 작성 → 핵심 키워드만 메모 → 자연스럽게 말하기가 답입니다. (1) 답안 100% 작성. (2) 핵심 키워드 5~10개 메모. (3) 100번 연습. (4) 메모만 보고 발표. 자연스러운 발표 = 자신감 + 즉흥 대응 + 평가 만점이에요."},
      {q: "수행평가 점수가 안 나와요. 무엇이 문제일까요?", a: "보통 3가지 약점 중 하나예요. (1) 답안 구조 약점 (논리 부족·근거 X). (2) 발음·유창성 약점 (한국식 발음·멈춤 잦음). (3) 자신감 약점 (긴장·실수). 무료 체험 수업에서 약점 진단 후 맞춤 학습이 답이에요. 한 학기 1:1 과외 + 매주 첨삭이면 큰 변화 체감해요."},
      {q: "1:1 화상 수업으로 수행평가 대비가 효과적인가요?", a: "매우 효과적이에요. (1) 학생 학교·평가 유형 정밀 분석. (2) 답안 매주 첨삭. (3) 발표 시뮬레이션 + 녹음. (4) 발음 교정 + 자신감 코칭. (5) 평가 직전 마지막 점검. 그룹 수업은 다른 학생 시선·발표 시간 짧음·맞춤 어려움. 1:1은 50분 풀 발화 + 정밀 첨삭. 제나쌤 스터디핏은 학교별 맞춤 + 정밀 첨삭으로 진행합니다."},
    ],
