      body: "국제학교는 영어로 진행되는 학교라 영어 실력이 학업 성공의 핵심이에요. 한국 학생들이 국제학교에서 어려워하는 이유는 \"영어 환경 적응·학과 영어·문화 적응\" 3가지예요. 핵심은 \"영어 환경 적응 + 학과 영어 + ESL + 자신감\" 4박자입니다. 1:1 화상 국제학교 대비는 입학 전 준비·재학 중 학습·유학 준비 모두 가능해요. 학습 단계: (1) 입학 시험 대비 (영어·수학·면접) → (2) 영어 환경 적응 → (3) 학과 영어 (수학·과학·사회 영어 어휘) → (4) 자신감 + 문화 적응. 6개월~1년 학습 → \"국제학교 입학 + 학업 적응\" 가능. 매일 1시간 + 주 2~3회 1:1 코칭이 가장 효과적인 국제학교 루틴이에요. 입학 전 1년 + 재학 중 평생 학습이 표준이에요."
