    checklistTitle: "국제학교 영어 체크리스트",
    checklistSub: "월 1회 점검",
    faqs: [
      {q: "국제학교 입학에 영어가 얼마나 필요한가요?", a: "학교·학년에 따라 달라요. (1) 초등: 기초 회화 + 간단한 작문 + 영어 수학 어휘. (2) 중등: 중급 회화 + 작문 + 학과 영어 (수학·과학). (3) 고등: 고급 회화 + 에세이 + 모든 학과 영어. 학교별 차이도 큼: GSIS·KIS·SFS·BFS·RSIS. 본인 학교·학년 분석 + 6~12개월 준비가 표준이에요. 무료 체험 수업에서 진단 + 맞춤 학습 가능합니다."},
      {q: "국제학교 학생도 1:1 과외가 필요한가요?", a: "매우 필요해요. 국제학교는 100% 영어라 보조 학습이 효과적이에요. (1) 학과 영어: 수학·과학·사회·영어 어휘 정밀 학습. (2) 작문 첨삭: 에세이·리포트·자기소개서. (3) 시험 대비: SAT·AP·IB·내신. (4) 자신감 코칭: 발표·토론·면접. 학교 ESL은 그룹이라 정밀 첨삭 어렵지만 1:1은 본인 약점만 집중 가능. 매주 1~2회 1:1 과외가 표준이에요."},
      {q: "국제학교에서 한국 학생이 가장 어려워하는 영역은?", a: "보통 3가지 영역이에요. (1) 작문 (Essay·Report): 한국 학생의 가장 큰 약점. 매주 첨삭 필수. (2) 토론 (Discussion·Debate): 의견 표현·반박·자신감. (3) 학과 영어 (Math·Science·Social): 학과별 어휘 200~500개. 1:1 과외에서 작문·토론·학과 영어 정밀 학습이 답이에요. 6개월~1년 집중 학습 → 큰 변화 체감해요."},
      {q: "국제학교 후 미국·영국 대학 진학은 어떻게 준비하나요?", a: "재학 3~4년차부터 입시 준비가 표준이에요. (1) SAT·ACT 대비: 미국 대학용. (2) AP·IB 시험: 고교 학점 + 대학 인정. (3) TOEFL/IELTS: 영어 비원어민용 시험. (4) 에세이: Common App·Personal Statement. (5) 추천서·과외 활동·면접. 1:1 과외에서 입시 정밀 대비·에세이 첨삭이 답이에요. 명문대 진학은 1~2년 집중 준비가 답입니다."},
      {q: "1:1 화상 수업으로 국제학교 대비가 효과적인가요?", a: "매우 효과적이에요. (1) 학생 학교·학년·약점 정밀 분석. (2) 작문·에세이 매주 첨삭. (3) 학과 영어 (수학·과학·사회) 정밀 학습. (4) 발표·토론 시뮬레이션. (5) SAT·AP·IB 정밀 대비. 학교 ESL은 그룹이라 정밀 학습 어렵지만 1:1은 본인 약점만 집중. 제나쌤 스터디핏은 국제학교 입학 + 재학 + 입시 + 유학까지 종합 대비 가능합니다."},
    ],
