      body: "외고는 한국 최상위권 영어·외국어 특성화 고등학교예요. 학생들이 외고 입학·재학에서 어려워하는 이유는 \"입학 시험 경쟁·고난도 영어 수업·내신 1등급 경쟁\" 3가지예요. 외고 영어의 핵심은 \"입학 시험 정밀 대비 + 재학 영어 학습 + 내신 1등급 + 진학 준비\" 4박자입니다. 1:1 화상 외고 대비는 입학 전 준비부터 재학 중 학습까지 종합 가능해요. 학습 단계: (1) 입학 시험 대비 (영어·면접·자기소개서) → (2) 입학 후 영어 환경 적응 → (3) 내신 1등급 + 수능 영어 → (4) 진학 준비 (수시·정시). 1년~2년 학습 → \"외고 입학 + 내신 1등급\" 가능. 매일 1시간~1.5시간 + 주 2~3회 1:1 코칭이 가장 효과적인 외고 루틴이에요."
